/** The confirmation page `/#/order-completion/<order ID>`. */
export class OrderCompletionPage {
  constructor(private readonly page: Page) {}

  async expectOpen(): Promise<string> {
    await expect(this.page).toHaveURL(/#\/order-completion\/.+/);
    await expect(this.page.getByText('Thank you for your purchase!')).toBeVisible();
    const match = /#\/order-completion\/([^/?#]+)/.exec(this.page.url());
    if (!match) {
      throw new Error(`No order ID in URL: ${this.page.url()}`);
    }
    return decodeURIComponent(match[1]);
  }
}
